<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {useRouter,useRoute} from 'vue-router'
import {coaching,teachers,type Overview,type PointInsight,type CoachSession,type Memory} from '@/api/coaching'
import {foundation} from '@/api/foundation'
import {learningApi} from '@/api/learning'
import {messageOf} from '@/api/client'
import type {KnowledgeBase,Citation} from '@/api/types'
import SafeAnswer from '@/components/SafeAnswer.vue'
import SpeakButton from '@/components/SpeakButton.vue'
import CitationReader from '@/components/CitationReader.vue'
const router=useRouter(),route=useRoute(),data=ref<Overview>(),busy=ref(false),error=ref(''),notice=ref(''),selected=ref(''),teacher=ref('encouraging'),bases=ref<KnowledgeBase[]>([]),kb=ref(''),lesson=ref<CoachSession|null>(null),choice=ref<number|null>(null),source=ref<Citation|null>(null),memory=ref(''),memoryKind=ref<'goal'|'preference'|'doubt'>('preference'),search=ref('')
const point=computed(()=>data.value?.Points.find(p=>p.ID===selected.value))
const subjects=computed(()=>[...new Map((data.value?.Points??[]).map(p=>[p.SubjectID,p.SubjectName])).entries()].sort((a,b)=>['数据结构','计算机组成原理','操作系统','计算机网络'].indexOf(a[1])-['数据结构','计算机组成原理','操作系统','计算机网络'].indexOf(b[1])))
const recommendations=computed(()=>data.value?.Points.filter(p=>p.AvailableQuestions>0).slice(0,8)??[])
const filteredPoints=computed(()=>data.value?.Points.filter(p=>p.Name.includes(search.value)||p.Code.includes(search.value))??[])
const result=computed(()=>lesson.value?.Assessment.Result?.Items[0])
function show(p:PointInsight){selected.value=p.ID}
async function act(fn:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=messageOf(e)}finally{busy.value=false}}
async function refresh(){data.value=await coaching.overview();if(!selected.value)selected.value=recommendations.value[0]?.ID??data.value.Points.find(p=>p.Code==='DS.BASIC')?.ID??data.value.Points[0]?.ID??'';const pref=data.value.Memories.find(m=>m.Key==='teacher');if(pref&&teachers.some(t=>t.id===pref.Content))teacher.value=pref.Content}
async function initial(){await act(async()=>{await refresh();if(typeof route.query.point==='string'&&data.value?.Points.some(p=>p.ID===route.query.point))selected.value=route.query.point;bases.value=await learningApi.bases();kb.value=bases.value.find(b=>b.IsPublic)?.ID??bases.value[0]?.ID??'';const sessions=await coaching.sessions();lesson.value=sessions[0]??null})}
async function plan(){await act(async()=>{await foundation.generate();await router.push('/exam408/tasks')})}
async function saveTeacher(){await act(async()=>{await coaching.memory({Key:'teacher',PointID:'',Kind:'preference',Content:teacher.value,Resolved:false});await refresh()})}
async function teach(){if(!point.value)return;await act(async()=>{lesson.value=await coaching.start({PointID:selected.value,KnowledgeBaseID:kb.value,Teacher:teacher.value});choice.value=null})}
async function answer(){if(!lesson.value||choice.value===null)return;await act(async()=>{const a=lesson.value!.Assessment,q=a.Questions[0];if(!q)return;a.Result=await foundation.submit(a.ID,{[q.ID]:choice.value!});await refresh();await foundation.generate();notice.value='本次作答已保存，学习方案已更新。正在整理老师详解。';try{lesson.value!.Feedback=await coaching.explain(lesson.value!.ID);notice.value='老师详解已通过原文核验。先核对步骤，再继续下一节。'}catch(e){notice.value='作答与学习方案已保存；老师详解暂未完成，先展示原文解析：'+messageOf(e)}})}
async function addMemory(){await act(async()=>{await coaching.memory({Key:crypto.randomUUID(),PointID:memoryKind.value==='doubt'?selected.value:'',Kind:memoryKind.value,Content:memory.value,Resolved:false});memory.value='';await refresh()})}
async function editMemory(m:Memory){const text=window.prompt('修改这条学习记忆',m.Content);if(text===null)return;await act(async()=>{await coaching.memory({...m,Content:text});await refresh()})}
async function resolve(m:Memory){await act(async()=>{await coaching.memory({...m,Resolved:!m.Resolved});await refresh()})}
async function forget(m:Memory){await act(async()=>{await coaching.forget(m.Key);await refresh()})}
onMounted(initial)
</script>
<template><div class="learning-studio"><header class="page-head"><div><p class="eyebrow">你的 408 学习空间</p><h1>我的老师与学习方案</h1><p>按计划学习 · 老师讲解 · 随堂检查 · 持续更新</p></div><button class="secondary" :disabled="busy" @click="act(refresh)">更新学习状态</button></header>
<p v-if="error" class="notice error" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p><p v-if="busy" class="notice" role="status">正在处理，请稍候；老师讲解需要检索教材和调用模型。</p>
<p v-if="data?.NeedsPretest" class="notice">还没有提交过前测。建议先到 <RouterLink to="/exam408/assessment">测评学情完成诊断</RouterLink>，再回来安排学习。</p>
<section class="card section"><h2>优先学习这些知识点</h2><div class="priority-list"><button v-for="p in recommendations" :key="p.ID" :class="{selected:p.ID===selected}" @click="show(p)"><b>{{p.Name}}</b><span>{{p.State}} · {{p.AvailableQuestions}}个可练习题组</span><small>{{p.Tested?`最近有效题组 ${p.Correct}/${p.Tested}`:'尚无有效作答'}} · 待确认疑问 {{p.Doubts}}</small></button></div><p v-if="!recommendations.length">暂无已关联可靠题目的知识点，请先完成公共题库整理。</p></section>
<section class="studio-grid"><div class="card section"><h2>选择这节课要学什么</h2><label class="field">查找知识点<input v-model="search" aria-label="搜索课堂知识点" placeholder="知识点名称或编码"/></label><label class="field">当前课堂<select v-model="selected"><optgroup v-for="[id,name] in subjects" :key="id" :label="name"><option v-for="p in filteredPoints.filter(p=>p.SubjectID===id)" :key="p.ID" :value="p.ID">{{p.Name}} · {{p.State}}</option></optgroup></select></label><p>学习顺序结合重要性、有效作答和待确认疑问；计划不是考试成绩预测。</p><button class="secondary" :disabled="busy" @click="plan">更新并查看今日任务</button><p><RouterLink :to="{path:'/exam408/knowledge',query:{point:selected}}">查看知识思维导图与考频来源 →</RouterLink></p></div>
<div class="card section" v-if="point"><h2>{{point.Name}}</h2><p>{{point.Description}}</p><p><b>{{point.State}}</b> · 已测{{point.Tested}}个题组 · 可练习{{point.AvailableQuestions}}组</p><p>参考重要性 {{point.Importance.toFixed(1)}} / 5<br/><small>{{point.ImportanceBasis}}</small></p><p>本库真题：{{point.ExamYears}} / {{point.CorpusYears}}个本学科已识别年度涉及该点；不是完整历年真题考频。</p><div class="toolbar-actions"><RouterLink :to="{path:'/exam408/assistant',query:{question:`${point.Name}是什么？`}}">向老师提问</RouterLink><RouterLink :to="{path:'/exam408/assessment',query:{point:point.ID}}">该点专项练习</RouterLink><RouterLink :to="{path:'/exam408/assets',query:{point:point.ID}}">该知识点题库</RouterLink><RouterLink to="/exam408/graph">查看知识关系图</RouterLink></div>
<label class="field">选择老师<select v-model="teacher" :disabled="busy" @change="saveTeacher"><option v-for="t in teachers" :key="t.id" :value="t.id">{{t.name}}</option></select></label><p>{{teachers.find(t=>t.id===teacher)?.hint}}</p><label class="field">讲解资料范围<select v-model="kb"><option v-for="b in bases" :key="b.ID" :value="b.ID">{{b.Name}}{{b.IsPublic?'':' ＋ 公共教材'}}</option></select></label><button class="primary" :disabled="busy||!kb||!point.AvailableQuestions" @click="teach">开始一对一讲解与随堂提问</button>
</div></section>
<section v-if="lesson" class="card section lesson"><h2>老师的小课堂 · {{data?.Points.find(p=>p.ID===lesson?.PointID)?.Name}}</h2><p>{{teachers.find(t=>t.id===lesson?.Teacher)?.name}} · {{new Date(lesson.CreatedAt).toLocaleString()}}</p><SafeAnswer :text="lesson.Lesson.Answer" :citations="lesson.Lesson.Sources.length" @cite="n=>source=lesson!.Lesson.Sources[n]??null"/><SpeakButton :text="lesson.Lesson.Answer"/><details><summary>教材来源</summary><button v-for="(s,n) in lesson.Lesson.Sources" :key="n" class="secondary" @click="source=s">{{s.DocumentTitle}} · 第{{s.Page}}页</button></details>
<form v-if="!lesson.Assessment.Result" @submit.prevent="answer"><h3>先停一下，试着回答这个问题</h3><fieldset v-for="q in lesson.Assessment.Questions" :key="q.ID"><legend>{{q.Payload.Stem}}</legend><img v-for="(img,i) in q.Payload.Images??[]" :key="i" :src="img" alt="题目原图" style="max-width:100%"/><label v-for="(o,i) in q.Payload.Options" :key="i" class="answer-choice"><input v-model="choice" type="radio" :value="i" required :disabled="busy"/>{{String.fromCharCode(65+i)}}. {{o}}</label><label class="answer-choice"><input v-model="choice" type="radio" :value="-1" required :disabled="busy"/>暂时不会，请带我复习</label><p>关联知识点：{{data?.Points.find(p=>p.ID===q.PointID)?.Name}} · {{q.Payload.Source}}</p></fieldset><button class="primary" :disabled="busy||choice===null">提交回答，再看反馈</button></form>
<div v-else-if="result" class="feedback"><h3>{{result.Correct?'这一步答对了，继续核对理由。':'没关系，我们把这一步重新拆开看。'}}</h3><p>参考答案：{{String.fromCharCode(65+result.Answer)}} · 依据资料答案判分</p><p v-if="!lesson.Feedback" class="muted">原文参考解析（尚非模型整理的老师详解）</p><SafeAnswer :text="lesson.Feedback?.Answer??result.Explanation" :citations="lesson.Feedback?.Sources.length??0" @cite="n=>source=lesson!.Feedback?.Sources[n]??null"/><SpeakButton :text="lesson.Feedback?.Answer??result.Explanation"/><details v-if="lesson.Feedback?.Sources.length"><summary>详解依据与原题条件</summary><button v-for="(s,n) in lesson.Feedback.Sources" :key="n" class="secondary" @click="source=s">{{s.DocumentTitle}} · {{s.Location}}</button></details><p>先复述“题目条件 → 使用的定义或公式 → 推导 → 结论”。不确定的步骤可以继续向老师追问。</p><RouterLink :to="{path:'/exam408/assistant',query:{question:`请逐步解释这道题，保留条件和公式：${lesson.Assessment.Questions[0]?.Payload.Stem}\n${result.Explanation}`}}">请老师通俗地逐步详解 →</RouterLink><p>你的回答已经保存；系统会等待你选择下一节，不自动跳过。</p><button class="secondary" :disabled="busy" @click="teach">学习当前所选知识点的下一道检查题</button></div></section>
<section id="learning-memory" class="card section"><h2>老师记住了什么</h2><p>只保存你的目标、偏好和待确认疑问。你可以随时改正、标记解决或删除。疑问不会直接降低掌握度。</p><form class="toolbar-actions" @submit.prevent="addMemory"><select v-model="memoryKind" aria-label="记忆类型"><option value="preference">学习偏好</option><option value="goal">学习目标</option><option value="doubt">当前知识点的疑问</option></select><input v-model="memory" required maxlength="500" aria-label="新增学习记忆" placeholder="例如：希望老师先用简短例子解释，再讲公式"/><button class="secondary" :disabled="busy">保存</button></form><article v-for="m in data?.Memories??[]" :key="m.Key" class="memory"><span>{{m.Resolved?'已解决':'已记录'}} · {{m.Key==='teacher'?(teachers.find(t=>t.id===m.Content)?.name??m.Content):m.Content}}</span><div class="toolbar-actions"><button :disabled="busy" @click="editMemory(m)">修改</button><button v-if="m.Kind==='doubt'" :disabled="busy" @click="resolve(m)">{{m.Resolved?'重新关注':'标记解决'}}</button><button :disabled="busy" @click="forget(m)">删除记忆</button></div></article></section><CitationReader :source="source" @close="source=null"/></div></template>
<style scoped>.studio-grid{display:grid;align-items:start;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:20px;margin:20px 0}.priority-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px}.priority-list button{text-align:left;border:1px solid #dbeafe;background:#f8fafc;border-radius:12px;padding:14px;cursor:pointer}.priority-list span,.priority-list small{display:block;margin-top:8px;color:#64748b}.priority-list .selected{border-color:#2563eb;background:#eff6ff}.mind-overview{max-height:640px;overflow:auto;padding-right:8px}.mind-overview>details{margin:20px 0}.mind-overview>details>summary{font-weight:700;cursor:pointer}.frequency,.memory{padding:14px 0;border-bottom:1px solid #e2e8f0}.frequency blockquote{white-space:pre-wrap}.memory{display:flex;justify-content:space-between;gap:12px}.answer-choice{display:flex;gap:10px;align-items:center;padding:10px}.answer-choice input{width:auto}.lesson fieldset{border:1px solid #dbeafe;padding:20px;margin:20px 0}.feedback{background:#eff6ff;padding:20px;margin-top:20px;border-radius:12px}@media(max-width:850px){.studio-grid{grid-template-columns:1fr}.memory{flex-direction:column}}</style>
